// POC ONLY — poc/http-ingress — do not merge as production API
//
// Minimal Express server exposing POST /poc/async: serializes the incoming
// HTTP request into a plain-data envelope, starts a real `executeFlow`
// Temporal Workflow with that envelope as `startMsg.payload`, and responds
// 202 immediately (never awaits `handle.result()`). This proves PoC A: an
// ordinary HTTP request can act as fire-and-forget ingress into a durable
// Node-RED flow Workflow, with the Workflow surviving ingress-process death.
//
// Usage:
//   TEMPORAL_ADDRESS=127.0.0.1:7239 \
//   TEMPORAL_WORKFLOW_TASK_QUEUE=poc-http-ingress-a \
//   TEMPORAL_ACTIVITY_TASK_QUEUE=poc-http-ingress-a \
//   node poc/http-ingress/async-server.js
//
// See README.md in this directory for full experiment logs.

"use strict";

const express = require("express");
const path = require("path");
const fs = require("fs");
const { Client, Connection } = require("@temporalio/client");
const { extractWireGraph, extractNodeMeta } = require("../../lib/wireGraph");
const { computeFlowVersion } = require("../../lib/bootstrap");
const { resolveTemporalConfig } = require("../../lib/worker");

const PORT = Number(process.env.POC_HTTP_PORT || 3939);
const FLOW_PATH = process.env.POC_FLOW_PATH || path.join(__dirname, "flow.json");
const START_NODE = process.env.POC_START_NODE || "n1";

const app = express();
app.use(express.json());

let clientPromise;
function getClient() {
    if (!clientPromise) {
        const temporalConfig = resolveTemporalConfig({});
        clientPromise = Connection.connect({ address: temporalConfig.address }).then((connection) => ({
            client: new Client({ connection, namespace: temporalConfig.namespace }),
            temporalConfig
        }));
    }
    return clientPromise;
}

// Reads the incoming request into a fully serializable envelope: no req/
// res/socket reference is ever placed on the envelope, only plain data.
function toEnvelope(req) {
    return {
        method: req.method,
        url: req.originalUrl,
        headers: Object.assign({}, req.headers),
        query: Object.assign({}, req.query),
        body: req.body
    };
}

app.post("/poc/async", async (req, res) => {
    try {
        const envelope = toEnvelope(req);

        const flows = JSON.parse(fs.readFileSync(FLOW_PATH, "utf8"));
        const graph = extractWireGraph(flows);
        const nodeMeta = extractNodeMeta(flows);
        const flowVersion = computeFlowVersion(flows);

        const { client, temporalConfig } = await getClient();
        const workflowId = `poc-http-ingress-${Date.now()}`;
        const handle = await client.workflow.start("executeFlow", {
            taskQueue: temporalConfig.workflowTaskQueue,
            workflowId,
            args: [{
                graph,
                nodeMeta,
                flowVersion,
                startNode: START_NODE,
                startMsg: { payload: envelope },
                activityTaskQueue: temporalConfig.activityTaskQueue
            }]
        });

        // Deliberately NOT awaiting handle.result() — fire-and-forget 202.
        console.log(`[poc-async] started workflow ${handle.workflowId} (runId ${handle.firstExecutionRunId})`);
        res.status(202).json({ workflowId: handle.workflowId, runId: handle.firstExecutionRunId });
    } catch (err) {
        console.error("[poc-async] error starting workflow:", err);
        res.status(500).json({ error: err.message });
    }
});

app.listen(PORT, () => {
    console.log(`[poc-async] listening on http://127.0.0.1:${PORT}/poc/async`);
    console.log(`[poc-async] flow=${FLOW_PATH} startNode=${START_NODE}`);
});
